// Renders the LED matrix as an interactive SVG, positioned from the real
// board layout (webui/board_data.js, generated by
// tools/extract_board_data.py -- see docs/LEDPWM_MATRIX.md). Board
// coordinates are millimeters with the same origin/orientation KiCad uses;
// this file just wraps them in a viewBox, no transform needed.
'use strict';

const SVG_NS = 'http://www.w3.org/2000/svg';
// MATRIX_MODE=PA24 (CH643RM.PDF 24.2.2, "8-column RGB Internal Drive") --
// 16 COM/rows (PB0-15), 24 addressable columns (8 groups x R/G/B channels,
// PA0-23). See docs/LEDPWM_MATRIX.md. Shared across all webui/*.js files
// (loaded before them) rather than redefined per file.
const MATRIX_ROWS = 16;
const MATRIX_COLS = 24;
const PIXEL_COUNT = MATRIX_ROWS * MATRIX_COLS;
const LED_RADIUS = 1.05; // mm, tuned by eye against the board's LED pitch

class BoardView {
	constructor(container) {
		this.container = container;
		this.frame = new Uint8Array(PIXEL_COUNT); // row-major, index = row*16+col
		this.dotByIndex = new Array(PIXEL_COUNT).fill(null);
		this.rgbDotByRef = new Map();
		// Which RGB LEDs' displayed color depends on a given (row, col)
		// cell -- an RGB LED's three channels are three ordinary cells in
		// the same `frame` array (see docs/LEDPWM_MATRIX.md), so painting
		// one of those cells needs to refresh that LED's swatch too.
		this._rgbRefsByCell = new Map();
		this.onPaintAt = null; // (xMillimeters, yMillimeters) => void, called while the user draws
		this.onSelectRgb = null; // (rgbLedInfo) => void, called on clicking an RGB LED
		// When true, the RGB LEDs are paint targets (dragging over them calls
		// onPaintAt like anywhere else) instead of opening onSelectRgb.
		this.rgbBrush = false;
		this._painting = false;
		this._build();
	}

	_build() {
		const xs = BOARD_DATA.outline.map((p) => p[0]);
		const ys = BOARD_DATA.outline.map((p) => p[1]);
		const pad = 4;
		const minX = Math.min(...xs) - pad;
		const minY = Math.min(...ys) - pad;
		const w = Math.max(...xs) - minX + pad;
		const h = Math.max(...ys) - minY + pad;
		// Exposed so other code (webui/video_import.js, mapping a video frame
		// onto the board) can sample at exactly the same framing this view
		// renders at, instead of recomputing/duplicating this padding logic.
		this.bounds = { minX, minY, width: w, height: h };

		const svg = document.createElementNS(SVG_NS, 'svg');
		svg.setAttribute('viewBox', `${minX} ${minY} ${w} ${h}`);
		svg.classList.add('board-svg');

		const outline = document.createElementNS(SVG_NS, 'polygon');
		outline.setAttribute(
			'points',
			BOARD_DATA.outline.map((p) => `${p[0]},${p[1]}`).join(' ')
		);
		outline.classList.add('board-outline');
		svg.appendChild(outline);

		// Silkscreen artwork, between the PCB and the LEDs. starfish_silkscreen.svg
		// is a 210x297mm Inkscape page at real scale, sharing its page
		// coordinates with the hardware repo's design/starfish_outline.svg --
		// so placing it is a pure translation: that outline's page-space
		// bounding box top-left (0.050189, 0.064966) onto BOARD_DATA.outline's.
		const outlineMinX = Math.min(...xs);
		const outlineMinY = Math.min(...ys);
		const clip = document.createElementNS(SVG_NS, 'clipPath');
		clip.id = 'board-clip';
		clip.appendChild(outline.cloneNode());
		const defs = document.createElementNS(SVG_NS, 'defs');
		defs.appendChild(clip);
		svg.appendChild(defs);
		const silkscreen = document.createElementNS(SVG_NS, 'image');
		silkscreen.setAttribute('href', 'starfish_silkscreen.svg');
		silkscreen.setAttribute('x', outlineMinX - 0.050189);
		silkscreen.setAttribute('y', outlineMinY - 0.064966);
		silkscreen.setAttribute('width', 210);
		silkscreen.setAttribute('height', 297);
		silkscreen.setAttribute('preserveAspectRatio', 'none');
		silkscreen.setAttribute('clip-path', 'url(#board-clip)');
		silkscreen.classList.add('board-silkscreen');
		svg.appendChild(silkscreen);

		// Lit LEDs glow through a per-LED CSS drop-shadow scaled by their
		// level (see .led/.led-rgb in styles.css) -- a plain blur of a white
		// LED would vanish against the white PCB.
		const ledLayer = document.createElementNS(SVG_NS, 'g');
		for (const led of BOARD_DATA.leds) {
			const c = document.createElementNS(SVG_NS, 'circle');
			c.setAttribute('cx', led.x);
			c.setAttribute('cy', led.y);
			c.setAttribute('r', LED_RADIUS);
			c.classList.add('led');
			c.dataset.row = led.row;
			c.dataset.col = led.col;
			const title = document.createElementNS(SVG_NS, 'title');
			title.textContent = `${led.ref} -- row ${led.row}, col ${led.col}`;
			c.appendChild(title);
			ledLayer.appendChild(c);
			this.dotByIndex[led.row * MATRIX_COLS + led.col] = c;
		}

		for (const led of BOARD_DATA.rgb_leds) {
			// Diamond, not a circle, so RGB accent LEDs (a different click
			// target: a color picker, not the paint brush) are visually
			// obvious at a glance rather than indistinguishable from mono
			// LEDs until clicked.
			const c = document.createElementNS(SVG_NS, 'rect');
			const s = LED_RADIUS * 1.8;
			c.setAttribute('x', led.x - s / 2);
			c.setAttribute('y', led.y - s / 2);
			c.setAttribute('width', s);
			c.setAttribute('height', s);
			c.setAttribute('transform', `rotate(45 ${led.x} ${led.y})`);
			c.classList.add('led-rgb');
			const title = document.createElementNS(SVG_NS, 'title');
			title.textContent = `${led.ref} -- RGB accent LED, col ${led.col} (click to set color)`;
			c.appendChild(title);
			c.addEventListener('click', (ev) => {
				ev.stopPropagation();
				if (!this.rgbBrush && this.onSelectRgb) this.onSelectRgb(led);
			});
			ledLayer.appendChild(c);
			this.rgbDotByRef.set(led.ref, c);
			// An RGB LED's three channels share one column (its shared anode
			// group) but each channel is a different row -- see
			// docs/LEDPWM_MATRIX.md and tools/extract_board_data.py.
			for (const row of [led.row, led.green_row, led.blue_row]) {
				const cell = row * MATRIX_COLS + led.col;
				if (!this._rgbRefsByCell.has(cell)) this._rgbRefsByCell.set(cell, []);
				this._rgbRefsByCell.get(cell).push(led.ref);
			}
		}
		svg.appendChild(ledLayer);

		this._wirePointerEvents(svg);

		this.container.innerHTML = '';
		this.container.appendChild(svg);
		this.svg = svg;
	}

	_wirePointerEvents(svg) {
		const paintAt = (ev) => {
			if (!this.onPaintAt) return;
			const pt = svg.createSVGPoint();
			pt.x = ev.clientX;
			pt.y = ev.clientY;
			const mm = pt.matrixTransform(svg.getScreenCTM().inverse());
			this.onPaintAt(mm.x, mm.y);
		};
		svg.addEventListener('pointerdown', (ev) => {
			// Capturing the pointer here (needed so drag-painting keeps
			// working even once the cursor leaves the svg's bounds) would
			// retarget the click synthesized from the matching pointerup to
			// the svg element instead of whatever was actually clicked --
			// which would silently break the RGB LEDs' own click listeners.
			// Let clicks on those fire normally instead.
			if (ev.target.closest('.led-rgb') && !this.rgbBrush) return;
			this._painting = true;
			svg.setPointerCapture(ev.pointerId);
			paintAt(ev);
		});
		svg.addEventListener('pointermove', (ev) => {
			if (this._painting) paintAt(ev);
		});
		for (const type of ['pointerup', 'pointercancel', 'pointerleave']) {
			svg.addEventListener(type, () => {
				this._painting = false;
			});
		}
	}

	setPixel(row, col, brightness) {
		if (row < 0 || row >= MATRIX_ROWS || col < 0 || col >= MATRIX_COLS) return;
		const cell = row * MATRIX_COLS + col;
		this.frame[cell] = brightness;
		const dot = this.dotByIndex[cell];
		if (dot) dot.style.setProperty('--level', brightness / 255);
		this._refreshRgbAtCell(cell);
	}

	setFrame(frame) {
		this.frame.set(frame);
		for (let i = 0; i < PIXEL_COUNT; i++) {
			const dot = this.dotByIndex[i];
			if (dot) dot.style.setProperty('--level', this.frame[i] / 255);
		}
		for (const led of BOARD_DATA.rgb_leds) this._refreshRgbSwatch(led);
	}

	_refreshRgbAtCell(cell) {
		const refs = this._rgbRefsByCell.get(cell);
		if (!refs) return;
		for (const ref of refs) {
			const led = BOARD_DATA.rgb_leds.find((l) => l.ref === ref);
			if (led) this._refreshRgbSwatch(led);
		}
	}

	_refreshRgbSwatch(led) {
		const dot = this.rgbDotByRef.get(led.ref);
		if (!dot) return;
		const [r, g, b] = this.getRgb(led);
		const lit = r || g || b;
		// Unlit: fall back to the CSS package color rather than black
		dot.style.fill = lit ? `rgb(${r}, ${g}, ${b})` : '';
		dot.style.setProperty('--glow', lit ? `rgb(${r}, ${g}, ${b})` : 'transparent');
	}

	// Each RGB LED's three channels are three ordinary cells in `frame`
	// (see docs/LEDPWM_MATRIX.md) -- these are just convenience wrappers
	// around setPixel()/frame reads for those three cells.
	getRgb(led) {
		return [
			this.frame[led.row * MATRIX_COLS + led.col],
			this.frame[led.green_row * MATRIX_COLS + led.col],
			this.frame[led.blue_row * MATRIX_COLS + led.col],
		];
	}

	setRgb(led, r, g, b) {
		this.setPixel(led.row, led.col, r);
		this.setPixel(led.green_row, led.col, g);
		this.setPixel(led.blue_row, led.col, b);
	}

	getFrame() {
		return this.frame.slice();
	}

	clear() {
		this.setFrame(new Uint8Array(PIXEL_COUNT));
	}
}
